   346  static void sc_asn1_print_generalizedtime(const u8 * buf, size_t buflen)
   347  {
   348          if (buflen < 8) {
   349                  printf("Error in decoding.\n");
   350                  return;
   351          }
   352
   353          print_ascii(buf, 2);
   354          sc_asn1_print_utctime(buf + 2, buflen - 2);
   355  }
