   514  const u8 *sc_asn1_skip_tag(sc_context_t *ctx, const u8 ** buf, size_t *buflen,
   515                             unsigned int tag_in, size_t *taglen_out)
   516  {
   517          const u8 *p = *buf;
   518          size_t len = *buflen, taglen;
   519          unsigned int cla = 0, tag;
   520
   521          if (sc_asn1_read_tag((const u8 **) &p, len, &cla, &tag, &taglen) != SC_SUCCESS
   522                          || p == NULL)
   523                  return NULL;
   524          switch (cla & 0xC0) {
   525          case SC_ASN1_TAG_UNIVERSAL:
   526                  if ((tag_in & SC_ASN1_CLASS_MASK) != SC_ASN1_UNI)
   527                          return NULL;
   528                  break;
   529          case SC_ASN1_TAG_APPLICATION:
   530                  if ((tag_in & SC_ASN1_CLASS_MASK) != SC_ASN1_APP)
   531                          return NULL;
   532                  break;
   533          case SC_ASN1_TAG_CONTEXT:
   534                  if ((tag_in & SC_ASN1_CLASS_MASK) != SC_ASN1_CTX)
   535                          return NULL;
   536                  break;
   537          case SC_ASN1_TAG_PRIVATE:
   538                  if ((tag_in & SC_ASN1_CLASS_MASK) != SC_ASN1_PRV)
   539                          return NULL;
   540                  break;
   541          }
   542          if (cla & SC_ASN1_TAG_CONSTRUCTED) {
   543                  if ((tag_in & SC_ASN1_CONS) == 0)
   544                          return NULL;
   545          } else
   546                  if (tag_in & SC_ASN1_CONS)
   547                          return NULL;
   548          if ((tag_in & SC_ASN1_TAG_MASK) != tag)
   549                  return NULL;
   550          len -= (p - *buf);      /* header size */
   551          if (taglen > len) {
   552                  sc_debug(ctx, SC_LOG_DEBUG_ASN1,
   553                           "too long ASN.1 object (size %"SC_FORMAT_LEN_SIZE_T"u while only %"SC_FORMAT_LEN_SIZE_T"u available)\n",
   554                           taglen, len);
   555                  return NULL;
   556          }
   557          *buflen -= (p - *buf) + taglen;
   558          *buf = p + taglen;      /* point to next tag */
   559          *taglen_out = taglen;
   560          return p;
