   624  int sc_asn1_decode_bit_string(const u8 * inbuf, size_t inlen,
   625                                void *outbuf, size_t outlen)
   626  {
   627          return decode_bit_string(inbuf, inlen, outbuf, outlen, 1);
   628  }
